sys_script_include.script:
var DemandMgmtDataSeparationUtil = Class.create();
DemandMgmtDataSeparationUtil.getActivePortfolioIdsForIdea = function(current){
	return '';
};
DemandMgmtDataSeparationUtil.getActiveBusinessUnitIdsForIdea = function(current){
	return '';
};
DemandMgmtDataSeparationUtil.getActiveDepartmentIdsForIdea = function(current){
	return (current && current.business_unit) ? 'business_unit=' + current.business_unit : '';
};
DemandMgmtDataSeparationUtil.getActivePortfolioIdsForDemand = function(current){
	return "sys_class_name="+SNC.PPMConfig.getPortfolioTable(current.getTableName());
};
DemandMgmtDataSeparationUtil.getActiveBusinessUnitIdsForDemand = function(current){
	return '';
};
DemandMgmtDataSeparationUtil.getActiveDepartmentIdsForDemand = function(current){
	return (current && current.business_unit) ? 'business_unit=' + current.business_unit : '';
};
DemandMgmtDataSeparationUtil.getDefaultBusinessUnitIdForDemand = function(current){
	return '';
};
DemandMgmtDataSeparationUtil.getDefaultPortfolioIdForDemand = function(current){
	return '';
};
DemandMgmtDataSeparationUtil.getDefaultDepartmentIdForDemand = function(current){
	return '';
};
DemandMgmtDataSeparationUtil.getDefaultPortfolioIdForIdea = function(current){
	return '';
};
